sys_script_include.script:
var VariableMap = (function() {
    var VariableMapConstructor = Class.create();
    VariableMapConstructor.prototype = {
        _parent_sys_id: '',

        getParentSysID: function() {
            return this._parent_sys_id;
        },

        _parent_display_value: '',

        getParentDisplayValue: function() {
            return this._parent_display_value;
        },

        _parent_table_name: '',

        getParentTableName: function() {
            return this._parent_table_name;
        },

        _parent_class_name: '',

        getParentClassName: function() {
            return this._parent_class_name;
        },

        _parent_is_variable_set: false,

        parentIsVariableSet: function() {
            return this._parent_is_variable_set;
        },

        _parent_is_record_producer: false,

        parentIsRecordProducer: function() {
            return this._parent_is_record_producer;
        },

        _allVariables: [],

        _variableSets: [],

        getAllVariables: function() {
            return this._allVariables;
        },

        _bySysId: {},

        findVariableBySysId: function(sys_id) {
            var result = this._bySysId[sys_id];
            if (typeof result != 'undefined')
                return {
                    variable: result
                };
            if (!this._parent_is_variable_set)
                for (var i = 0; i < this._variableSets.length; i++) {
                    var var_set = this._variableSets[i];
                    result = var_set.getVariableBySysId(sys_id);
                    if (typeof result != 'undefined')
                        return {
                            variable: result,
                            variable_set: var_set
                        };
                }
        },

        getVariableBySysId: function(sys_id) {
            return this._bySysId[sys_id];
        },

        getNestedVariableBySysId: function(sys_id) {
            if (!this._parent_is_variable_set)
                for (var i = 0; i < this._variableSets.length; i++) {
                    result = this._variableSets[i].getVariableBySysId(sys_id);
                    if (typeof result != 'undefined')
                        return result;
                }
        },

        _byName: {},

        findVariableByName: function(varName) {
            var result = this._byName[varName];
            if (typeof result != 'undefined')
                return {
                    variable: result
                };
            if (!this._parent_is_variable_set)
                for (var i = 0; i < this._variableSets.length; i++) {
                    var var_set = this._variableSets[i];
                    result = var_set.getVariableByName(varName);
                    if (typeof result != 'undefined')
                        return {
                            variable: result,
                            variable_set: var_set
                        };
                }
        },

        getVariableByName: function(varName) {
            return this._byName[varName];
        },

        getNestedVariableByName: function(varName) {
            var result = this._byName[varName];
            if (!this._parent_is_variable_set)
                for (var i = 0; i < this._variableSets.length; i++) {
                    result = this._variableSets[i].getVariableByName(varName);
                    if (typeof result != 'undefined')
                        return result;
                }
        },

        /**
         * @param {MarkdownGenerationContext} context
         * @param {string[]} markdownLines
         */
        pushVariablesSectionMarkdown: function(context, markdownLines) {
            if (this._allVariables.length < 1)
                return;

            var i;
            /** @type {QuestionItem} */
            var item;
            var type, linkTxt;
            if (this._parent_is_record_producer) {
                markdownLines.push(
                    '',
                    '## Variables',
                    '',
                    '| Type | Question | Field | Order |',
                    '| ---- | -------- | ----- | ----- |'
                );
                for (i = 0; i < this._allVariables.length; i++) {
                    item = this._allVariables[i];
                    type = item.type_label;
                    linkTxt = '[' + MarkdownGenerationContext.escapeForMarkdown(item.question_text ? item.question_text : item.name, true) + (item.set_map ? '](#variable-set-' : '](#variable-') + item.name + ')';
                    if (!item.set_map)
                        switch (item.type_value) {
                            case 19: // Container Start
                            case 24: // Container Split
                            case 20: // Container End
                                linkTxt = '*' + linkTxt + '*';
                                type = '*\\(' + type + '\\)*';
                                break;
                        }
                    markdownLines.push('| ' + type + ' | ' + linkTxt + ' | ' + (item.field ? item.field.display_value + ' | ' : '| ') + item.order.display_value + ' |');
                }
            } else {
                markdownLines.push(
                    '',
                    '## Variables',
                    '',
                    '| Type | Question | Order |',
                    '| ---- | -------- | ----- |'
                );
                for (i = 0; i < this._allVariables.length; i++) {
                    item = this._allVariables[i];
                    type = item.type_label;
                    linkTxt = '[' + MarkdownGenerationContext.escapeForMarkdown(item.question_text ? item.question_text : item.name) + (item.set_map ? '](#variable-set-' : '](#variable-') + item.name + ')';
                    if (!item.set_map)
                        switch (item.type_value) {
                            case 19: // Container Start
                            case 24: // Container Split
                            case 20: // Container End
                            linkTxt = '*' + linkTxt + '*';
                                type = '*\\(' + type + '\\)*';
                                break;
                        }
                    markdownLines.push('| ' + type + ' | ' + linkTxt + ' | ' + item.order.display_value + ' |');
                }
            }
            for (i = 0; i < this._allVariables.length; i++) {
                item = this._allVariables[i];
                /** @type {LabeledMultilineStackItem[]} */
                var multiLineStack = [];
                if (item.set_map) {
                    varSetGr = new GlideRecord('item_option_new_set');
                    varSetGr.get(allVariables[i].sys_id);
                    markdownLines.push('');
                    markdownLines.push("### Variable Set: " + varSetGr.getValue('internal_name'));
                    markdownLines.push('');

                    markdownLines.push('- **Title:** [' + MarkdownGenerationContext.escapeForMarkdown(gs.nil(varSetGr.title) ? varSetGr.getValue('internal_name') : varSetGr.getValue('title')) + '](' + context.mapper.getVarSetUrl(varSetGr, context.getCurrentFolder()) + ')');
                    markdownLines.push('- **Order:** ' + order);
                    context.pushDisplayValueListItem(varSetGr.type, markdownLines, multiLineStack);
                    context.pushListItemIfTrue(varSetGr.display_title, markdownLines);
                    context.pushDisplayValueListItem(varSetGr.layout, markdownLines, multiLineStack);
                    context.pushDisplayValueListItem(varSetGr.description, markdownLines, multiLineStack);
                    context.pushMultiLineItems(multiLineStack, markdownLines);
                } else {
                    variableGr = new GlideRecord('item_option_new');
                    variableGr.get(allVariables[i].sys_id);
                    markdownLines.push('');
                    markdownLines.push("### Variable: " + varGr.getValue('name'));
                    markdownLines.push('');

                    if (varGr.getDisplayValue('map_to_field') == 'true') {
                        markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(varGr.map_to_field.getLabel()) + ':** True');
                        markdownLines.push(context.getColumnReferenceMdLink(varGr.record_producer_table, varGr.field));
                    }
                    context.pushDisplayValueListItem(varGr.type, markdownLines, multiLineStack);
                    context.pushDisplayValueListItem(varGr.question_text, markdownLines, multiLineStack);
                    context.pushDisplayValueListItem(varGr.conversational_label, markdownLines, multiLineStack);
                    context.pushDisplayValueListItem(varGr.tooltip, markdownLines, multiLineStack);
                    context.pushDisplayValueListItem(varGr.order, markdownLines, multiLineStack);
                    context.pushListItemIfTrue(varGr.show_help, markdownLines);
                    if (varGr.getDisplayValue('show_help') == 'true') {
                        if (varGr.help_tag != 'More information')
                            context.pushValueListItem(varGr.help_tag, markdownLines, multiLineStack);
                        context.pushDisplayValueListItem(varGr.help_text, markdownLines, multiLineStack);
                        context.pushCodeListItem(varGr.instructions, 'html', markdownLines, multiLineStack);
                    }
                    var listChoices = false;
                    type = parseInt(varGr.getValue('type'));
                    switch (type) {
                        case 1: // Yes / No
                            context.pushListItemIfTrue(varGr.include_none, markdownLines);
                            break;
                        case 2: // Multi Line Text
                            context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                            break;
                        case 3: // Multiple Choice
                            context.pushDisplayValueListItem(varGr.choice_direction, markdownLines, multiLineStack);
                            context.pushListItemIfTrue(varGr.include_none, markdownLines);
                            context.pushListItemIfTrue(varGr.do_not_select_first, markdownLines);
                            context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                            listChoices = true;
                            break;
                        case 5: // Select Box
                        case 18: // Lookup Select Box
                            if (!gs.nil(varGr.choice_table)) {
                                context.pushTableReferenceListItem(varGr.choice_table, markdownLines);
                                context.pushFieldReferenceListItem(varGr.choice_table, varGr.choice_field, markdownLines);
                            }
                            context.pushListItemIfTrue(varGr.include_none, markdownLines);
                            context.pushListItemIfTrue(varGr.lookup_unique, markdownLines);
                            context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                            listChoices = true;
                            break;
                        case 8: // Reference
                            context.pushTableReferenceListItem(varGr.reference, markdownLines);
                            context.pushDisplayValueListItem(varGr.use_reference_qualifier, markdownLines, multiLineStack);
                            switch (varGr.getValue('use_reference_qualifier')) {
                                case 'simple':
                                    context.pushCodeListItem(varGr.reference_qual_condition, 'text', markdownLines, multiLineStack);
                                    break;
                                default:
                                    context.pushCodeListItem(varGr.reference_qual, 'text', markdownLines, multiLineStack);
                                    break;
                            }
                            context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                            break;
                        case 19: // Container Start
                            context.pushListItemIfTrue(varGr.display_title, markdownLines);
                            context.pushDisplayValueListItem(varGr.layout, markdownLines, multiLineStack);
                            break;
                        case 22: // Lookup Multiple Choice
                            context.pushDisplayValueListItem(varGr.lookup_source, markdownLines, multiLineStack);
                            switch (varGr.getValue('lookup_source')) {
                                case 'choice':
                                case 'choices':
                                    if (!gs.nil(varGr.choice_table)) {
                                        context.pushTableReferenceListItem(varGr.choice_table, markdownLines);
                                        context.pushFieldReferenceListItem(varGr.choice_table, varGr.choice_field, markdownLines);
                                    }
                                    break;
                            }
                            context.pushDisplayValueListItem(varGr.choice_direction, markdownLines, multiLineStack);
                            context.pushListItemIfTrue(varGr.include_none, markdownLines);
                            context.pushListItemIfTrue(varGr.lookup_unique, markdownLines);
                            context.pushValueListItem(varGr.reference_qual, markdownLines, multiLineStack);
                            context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                            break;
                        case 21: // List Collector
                            context.pushTableReferenceListItem(varGr.list_table, markdownLines);
                            context.pushDisplayValueListItem(varGr.use_reference_qualifier, markdownLines, multiLineStack);
                            switch (varGr.getValue('use_reference_qualifier')) {
                                case 'simple':
                                    context.pushCodeListItem(varGr.reference_qual_condition, 'text', markdownLines, multiLineStack);
                                    break;
                                default:
                                    context.pushCodeListItem(varGr.reference_qual, 'text', markdownLines, multiLineStack);
                                    break;
                            }
                            context.pushCodeListItem(varGr.attributes, 'text', markdownLines, multiLineStack);
                            break;
                        case 4: // Numeric Scale
                        case 6: // Single Line Text
                        case 7: // CheckBox
                        case 9: // Date
                        case 10: // Date/Time
                        case 11: // Label
                        case 12: // Break
                        case 14: // Custom
                        case 15: // UI Page
                        case 16: // Wide Single Line Text
                        case 17: // Custom with Label
                        case 20: // Container End
                        case 23: // HTML
                        case 24: // Container Split
                        case 25: // Masked
                        case 26: // Email
                        case 27: // URL
                        case 28: // IP Address
                        case 29: // Duration
                        case 31: // Requested For
                        case 32: // Rich Text Label
                        case 33: // Attachment
                        case 40: // Table Name
                            break;
                        default:
                            markdownLines.push("- **Unknown type:** *" + varGr.getValue('type') + '*');
                            break;
                    }

                    context.pushListItemIfTrue(varGr.global, markdownLines);
                    context.pushListItemIfTrue(varGr.disable_initial_slot_fill, markdownLines);
                    context.pushDisplayValueListItem(varGr.variable_width, markdownLines, multiLineStack);
                    context.pushListItemIfFalse(varGr.visible_standalone, markdownLines);
                    context.pushListItemIfFalse(varGr.visible_bundle, markdownLines);
                    context.pushListItemIfTrue(varGr.not_available_conversation, markdownLines);
                    context.pushListItemIfFalse(varGr.visible_guide, markdownLines);
                    context.pushListItemIfFalse(varGr.visible_summary, markdownLines);
                    switch (type) {
                        case 20: // Container End
                        case 24: // Container Split
                        case 32: // Rich Text Label
                            break;
                        case 19: // Container Start
                            context.pushListItemIfTrue(varGr.hidden, markdownLines);
                            break;
                        default:
                            context.pushListItemIfTrue(varGr.mandatory, markdownLines);
                            if (!varGr.mandatory) {
                                context.pushListItemIfTrue(varGr.hidden, markdownLines);
                                context.pushListItemIfTrue(varGr.read_only, markdownLines);
                            }
                            break;
                    }
                    switch (type) {
                        case 2: // Multi Line Text
                        case 7: // CheckBox
                        case 9: // Date
                        case 10: // Date/Time
                            context.pushCodeListItem(varGr.default_value, 'text', markdownLines, multiLineStack);
                            break;
                        case 1: // Yes / No
                        case 3: // Multiple Choice
                        case 4: // Numeric Scale
                        case 6: // Single Line Text
                        case 16: // Wide Single Line Text
                        case 18: // Lookup Select Box
                        case 26: // Email
                        case 27: // URL
                        case 28: // IP Address
                        case 29: // Duration
                        case 5: // Select Box
                            context.pushCodeListItem(varGr.default_value, 'text', markdownLines, multiLineStack, true);
                            break;
                        case 23: // HTML
                            if (gs.nil(varGr.default_html_value))
                                context.pushCodeListItem(varGr.default_value, 'text', markdownLines, multiLineStack, true);
                            else
                                context.pushCodeListItem(varGr.default_html_value, 'html', markdownLines, multiLineStack, true);
                            break;
                        case 32: // Rich Text Label
                            context.pushCodeListItem(varGr.rich_text, 'html', markdownLines, multiLineStack, true);
                            break;
                        case 19: // Container Start
                        case 20: // Container End
                        case 24: // Container Split
                            break;
                        default:
                            context.pushDisplayValueListItem(varGr.default_value, markdownLines, multiLineStack);
                            break;
                    }

                    context.pushDisplayValueListItem(varGr.example_text, markdownLines, multiLineStack);
                    context.pushDisplayValueListItem(varGr.validate_regex, markdownLines, multiLineStack);
                    context.pushDisplayValueListItem(varGr.roles_to_use_also_request_for, markdownLines, multiLineStack);
                    context.pushMultiLineItems(multiLineStack, markdownLines);

                    if (listChoices) {
                        var choiceGr = new GlideRecord('question_choice');
                        choiceGr.addQuery('question', varGr.sys_id);
                        choiceGr.addQuery('inactive', false);
                        choiceGr.orderBy('order');
                        choiceGr.query();
                        if (choiceGr.next()) {
                            markdownLines.push('');
                            markdownLines.push('**Choices:**');
                            markdownLines.push('');
                            markdownLines.push('| Label | Value | Sequence |');
                            markdownLines.push('| ----- | ----- | -------- |');
                            do {
                                markdownLines.push("| " + MarkdownGenerationContext.escapeForMarkdown(choiceGr.getValue('text'), true) + " | " + MarkdownGenerationContext.escapeForMarkdown(choiceGr.getValue('value'), true) + " | " + choiceGr.getDisplayValue('order') + " |");
                            } while (choiceGr.next());
                        }
                    }
                }
            }
        },

        initialize: function(parentGlideRecord) {
            if (gs.nil(parentGlideRecord))
                throw new Error("Parent record not provided.");
            if (parentGlideRecord instanceof GlideElement) {
                if (parentGlideRecord.getRefRecord) {
                    parentGlideRecord = parentGlideRecord.getRefRecord();
                    if (gs.nil(parentGlideRecord))
                        throw new Error("Parent record not provided.");
                } else
                    throw new Error("Parameter is not a record reference.");
            } else if (parentGlideRecord instanceof String) {
                var gr = new GlideRecord('sc_cat_item');
                if (gr.get(parentGlideRecord))
                    parentGlideRecord = gr;
                else {
                    gr = new GlideRecord('item_option_new_set');
                    if (gr.get(parentGlideRecord))
                        parentGlideRecord = gr;
                    else
                        throw new Error("Catalog item or Variable Set with ID " + JSON.stringify(parentGlideRecord) + " not found.");
                }
            } else if (!(parentGlideRecord instanceof GlideRecord || parentGlideRecord instanceof GlideRecord))
                throw new Error("Parameter must represent a Catalog Item or Variable Set.");

            this._parent_sys_id = parentGlideRecord.getUniqueValue();
            this._parent_display_value = MarkdownGenerationContext.escapeForMarkdown(parentGlideRecord.getDisplayValue());
            this._parent_table_name = parentGlideRecord.getTableName();
            this._parent_class_name = MarkdownGenerationContext.escapeForMarkdown(gr.getClassDisplayValue());
            if (gs.nil(this._parent_class_name))
                this._parent_class_name = this._parent_table_name;
            var variableGr = new GlideRecord('item_option_new');
            if (parentGlideRecord.instsanceOf('item_option_new')) {
                this._parent_is_variable_set = true;
                if (gs.nil(this._parent_display_value)) {
                    this._parent_display_value = parentGlideRecord.getValue('internal_name');
                    if (gs.nil(this._parent_display_value))
                        this._parent_display_value = this._parent_sys_id;
                }
                variableGr.addQuery('variable_set', this._parent_sys_id);

            } else if (parentGlideRecord.instsanceOf('sc_cat_item')) {
                if (gs.nil(this._parent_display_value))
                    this._parent_display_value = this._parent_sys_id;
                variableGr.addQuery('cat_item', this._parent_sys_id);
                this._parent_is_record_producer = parentGlideRecord.instsanceOf('sc_cat_item_producer');
            } else
                throw new Error("Parameter must represent a Catalog Item or Variable Set.");
            switch (this._parent_table_name) {
                case 'sc_cat_item':
                case 'sc_cat_item_producer':
                    break;
                case 'item_option_new':
                    break;
                default:
                    throw new Error("Parameter must represent a Catalog Item or Variable Set.");
            }
            variableGr.orderBy('order');
            variableGr.orderBy('name');
            variableGr.addActiveQuery();
            variableGr.query();
            /** @type {QuestionItem[]} */
            var allVariables = [];
            /** @type {QuestionItem} */
            var item;
            while (variableGr.next()) {
                item = {
                    sys_id: variableGr.getValue('sys_id'),
                    type_value: parseInt(variableGr.getValue('type')),
                    type_label: MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('type')),
                    question_text: gs.nil(variableGr.question_text) ? '' : MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('question_text')),
                    name: variableGr.getValue('name'),
                    order: gs.nil(variableGr.order) ? {
                        display_value: '',
                        value: NaN
                    } : {
                        display_value: variableGr.getDisplayValue('order'),
                        value: parseInt(variableGr.getValue('order'))
                    }
                };
                if (this._parent_is_record_producer && !gs.nil(variableGr.field))
                    item.field = {
                        value: MarkdownGenerationContext.escapeForMarkdown(variableGr.getValue('field')),
                        display_value: MarkdownGenerationContext.escapeForMarkdown(variableGr.getDisplayValue('field'))
                    };
                allVariables.push(item);
                this._bySysId[item.sys_id] = item;
                this._byName[item.name] = item;
            }
            if (this._parent_is_variable_set)
                this._allVariables = allVariables;
            else {
                var startingCount = allVariables.length;
                var varSetItemGr = new GlideRecord('io_set_item');
                varSetItemGr.addQuery('sc_cat_item', this._parent_sys_id);
                varSetItemGr.orderBy('order');
                varSetItemGr.orderBy('variable_set.internal_name');
                varSetItemGr.query();
                if (varSetItemGr.next()) {
                    do {
                        var varSetGr = varSetItemGr.variable_set.getRefRecord();
                        var setMap = new VariableMap(varSetGr);
                        item = {
                            sys_id: varSetItemGr.getValue('variable_set'),
                            type_value: NaN,
                            type_label: 'Variable Set',
                            question_text: setMap.getParentDisplayValue(),
                            name: varSetGr.getValue('internal_name'),
                            set_map: setMap,
                            order: gs.nil(varSetItemGr.order) ? {
                                display_value: '',
                                value: NaN
                            } : {
                                display_value: varSetItemGr.getDisplayValue('order'),
                                value: parseInt(varSetItemGr.getValue('order'))
                            }
                        };
                        this._variableSets.push(item);
                        allVariables.push(item);
                        this._bySysId[item.sys_id] = item;
                        this._byName[item.name] = item;
                    } while (varSetItemGr.next());
                    if (startingCount > 0)
                        this._allVariables = allVariables.sort(function(a, b) {
                            if (isNaN(a.order.value)) {
                                if (!isNaN(b.order.value))
                                    return -1;
                            } else {
                                if (isNaN(b.order.value))
                                    return 1;
                                var d = a.order.value - b.order.value;
                                if (d != 0)
                                    return d;
                            }
                            if (a.name < b.name)
                                return -1;
                            return (a.name > b.name) ? 1 : 0;
                        });
                    else
                        this._allVariables = allVariables;
                } else
                    this._allVariables = allVariables;
            }
            var container_name = '';
            for (var i = 0; i < this._allVariables.length; i++) {
                item = this._allVariables[i];
                    switch (item.type_value) {
                        case 19: // Container Start
                            container_name = item.question_text;
                            break;
                        case 24: // Container Split
                            if (container_name)
                                item.question_text = container_name;
                            break;
                        case 20: // Container End
                            if (container_name) {
                                item.question_text = container_name;
                                container_name = '';
                            }
                            break;
                    }
            }
        },

        type: 'VariableMap'
    };

    return VariableMapConstructor;
})();
